typedef uint32_t (*cublasLtRegisterProfileDomain)(const char* domain_name, const char** function_list, uint32_t function_number);
typedef uint8_t (*cublasLtIsProfileCallbackEnabled)(uint32_t domain, uint32_t callback_id);
typedef void (*cublasLtProfileCallbackBegin)(uint32_t domain, uint32_t callback_id);
typedef void (*cublasLtProfileCallbackEnd)(uint32_t domain, uint32_t callback_id);

struct cublasLtProfileHandler {
    cublasLtRegisterProfileDomain registerProfileDomain;
    cublasLtIsProfileCallbackEnabled isCallbackEnabled;
    cublasLtProfileCallbackBegin profileCallbackBegin;
    cublasLtProfileCallbackEnd profileCallbackEnd;
};

static cublasLtProfileHandler g_profileHandler;
static bool gDirectReturn = false;
static const char* gLibName = "cublasLt";

static void InitializeProfileHandler() {
    // get library patch
    const char* profile_tool_library = getenv("WRAPPER_INJECTION_PATH");
    if (profile_tool_library == NULL) {
        return;
    }

    // open profile library
    void* tool_handler = dlopen(profile_tool_library, RTLD_LAZY);
    if (!tool_handler) {
        printf("cannot open the file:%s  with error %s\n", profile_tool_library, dlerror());
        return;
    }

    // init profile handler
    g_profileHandler.registerProfileDomain = reinterpret_cast<cublasLtRegisterProfileDomain>(dlsym(tool_handler, "wrapperRegisterProfileDomain"));
    g_profileHandler.isCallbackEnabled = reinterpret_cast<cublasLtIsProfileCallbackEnabled>(dlsym(tool_handler, "wrapperIsProfileCallbackEnabled"));
    g_profileHandler.profileCallbackBegin = reinterpret_cast<cublasLtProfileCallbackBegin>(dlsym(tool_handler, "wrapperProfileCallbackBegin"));
    g_profileHandler.profileCallbackEnd = reinterpret_cast<cublasLtProfileCallbackEnd>(dlsym(tool_handler, "wrapperProfileCallbackEnd"));

    // register profile domain
    if (g_profileHandler.registerProfileDomain != NULL) {
        g_profileDomain = g_profileHandler.registerProfileDomain(gLibName, g_profileFunctionList, sizeof(g_profileFunctionList) / sizeof(g_profileFunctionList[0]));
        if (g_profileDomain == 0) {
            g_profileHandler.isCallbackEnabled = NULL;
        }
    }
}

